import sympy as S
from fractions import Fraction as F
from .authoring import maker,finish
from .common import section
q=maker('geometric-constructions',['auxiliary lines','area decomposition','reflection'])
sqrt=S.sqrt
p=[
q(1,r'A triangle has side lengths 13,14,15. What is its altitude to the side of length 14?',12,[(6,'Forget the factor one-half in area.'),(13,'Use a sloping side as the altitude.'),(14,'Use the base as the altitude.'),(10,'Assume the altitude bisects the base.')],[r'Place the base on a line and let the projection from the 13-side endpoint be x, with altitude h.',r'The equations $x^2+h^2=169$ and $(14-x)^2+h^2=225$ give x=5.',r'Then h²=169-25=144, so h=12.'],['Drop an altitude and label its foot rather than assuming it is a midpoint.','Subtract the two right-triangle equations.'],'Introduce a perpendicular that shares an unknown height.',lambda:2*sqrt(21*8*7*6)/14,'Heron area gives an independent altitude.',2),
q(2,r'An isosceles triangle has sides 13,13,10. What is its inradius?',F(10,3),[(5,'Use half the base.'),(F(20,3),'Forget the half in the area.'),(F(5,3),'Divide the area by the perimeter instead of the semiperimeter.'),(12,'Report the altitude.')],[r'The symmetry altitude bisects the base into lengths five, giving height twelve.',r'The area is 60 and the semiperimeter is 18.',r'Decomposing into three triangles from the incenter gives K=rs, hence r=60/18=10/3.'],['Use the symmetry altitude to obtain the area.','Express the same area using three triangles with common height r.'],'Connect an auxiliary altitude with an incircle area identity.',lambda:sqrt(18*5*5*8)/18,'Heron area divided by semiperimeter.',2),
q(3,r'An isosceles trapezoid has bases 10 and 26 and legs 10. Find its area.',108,[(180,'Use the leg as the height.'),(216,'Forget to average the bases.'),(144,'Use the horizontal offset as the height.'),(60,'Count only the central rectangle.')],[r'Drop perpendiculars from the shorter base. The two horizontal offsets are each (26-10)/2=8.',r'The height is $\sqrt{10^2-8^2}=6$.',r'The central rectangle has area 60 and the two end triangles have total area 48, giving 108.'],['Split the excess base length between the two congruent end triangles.','The leg is the hypotenuse, not the height.'],'Decompose a trapezoid into a rectangle and two right triangles.',lambda:F(10+26,2)*sqrt(100-64),'Independent trapezoid area formula after the height is established.',2),
q(4,r'In a right triangle with legs 6 and 8, what is the altitude to the hypotenuse?',F(24,5),[(5,'Use half the hypotenuse.'),(F(12,5),'Lose a factor two when changing bases.'),(10,'Report the hypotenuse.'),(F(48,5),'Omit the half in one area representation.')],[r'The hypotenuse is 10 by the Pythagorean theorem.',r'The area is 24 using the two legs, and also 10h/2.',r'Equating the two gives h=24/5.'],['Compute the area in two ways.','Changing the base changes the corresponding height.'],'Use area equality to avoid a second coordinate calculation.',lambda:abs(S.det(S.Matrix([[6,0],[0,8]])))/10,'Distance-to-line determinant for the hypotenuse.',2),
q(5,r'In triangle ABC, AB=13, AC=15, BC=14. The internal angle bisector from A meets BC at D. Find AD².',F(585,4),[(195,'Omit the correction for the opposite side.'),(148,'Use the median formula instead of the angle bisector.'),(F(195,4),'Retain only the subtracted portion.'),(169,'Assume the bisector is a side of a congruent triangle.')],[r'The angle-bisector theorem gives BD=13/2 and DC=15/2.',r'Stewart’s theorem gives $15^2(13/2)+13^2(15/2)=14(AD^2+(13/2)(15/2))$.',r'Solving gives $AD^2=585/4$. The theorem applies to this cevian whether or not it is perpendicular.'],['First determine the two segments on BC.','Use a length relation for a general cevian; it is not an altitude or median.'],'Combine an angle condition with a general cevian identity.',lambda:(S.Rational(13,2)-5)**2+12**2,'Coordinates B=(0,0), C=(14,0), A=(5,12), D=(13/2,0).'),
q(6,r'An equilateral triangle has side length $6\sqrt3$. A point lies strictly inside it. What is the sum of its perpendicular distances to the three sides?',9,[(18,'Double-count the three subtriangle areas.'),(6*sqrt(3),'Use the side length as the altitude.'),(3,'Report the inradius instead of the total.'),(F(9,2),'Omit the area factor one-half on one side of the equation.')],[r'Join the point to the three vertices, partitioning the original area.',r'All three subtriangles have the same base length, so their total area is side·(d1+d2+d3)/2.',r'Comparing with side·height/2 gives the altitude, $6\sqrt3\cdot\sqrt3/2=9$.'],['Join the interior point to every vertex.','Compute the total area using the three perpendicular distances.'],'Create an invariant by area decomposition.',lambda:sqrt(3)/2*(6*sqrt(3)),'Altitude computation; area partition proves independence from the interior point.'),
q(7,r'A triangle has sides AB=13, AC=15, BC=14. If M is the midpoint of BC, find AM².',148,[(144,'Use the altitude instead of the median.'),(196,'Use the base squared.'),(296,'Omit the denominator two in the median relation.'),(F(585,4),'Confuse the median with the angle bisector.')],[r'Extend AM by its own length to P. The diagonals AP and BC bisect each other, so ABPC is a parallelogram.',r'The parallelogram law gives $(2AM)^2+14^2=2(13^2+15^2)$.',r'Thus AM²=(338+450-196)/4=148.'],['Extend the median to create a parallelogram.','Its two diagonals connect the known side lengths to the unknown median.'],'Use a doubled median to expose a parallelogram identity.',lambda:(7-5)**2+12**2,'Independent coordinates from the two side-distance equations.'),
q(8,r'Points A=(0,3) and B=(8,5) lie above the x-axis. A point P on the x-axis minimizes AP+PB. What is the x-coordinate of P?',3,[(4,'Choose the horizontal midpoint without accounting for different heights.'),(5,'Reverse the ratio of the two vertical distances.'),(0,'Choose the foot from A without minimizing both segments.'),(8,'Choose the foot from B without minimizing both segments.')],[r'Reflect A to A′=(0,-3); then AP=A′P.',r'The shortest broken path A′PB is the straight segment A′B, which crosses the axis because its endpoints have opposite signs of y.',r'The crossing occurs 3/8 of the way from A′ to B, so its x-coordinate is 3.'],['Reflect one endpoint across the line on which P moves.','The triangle inequality then identifies the shortest path.'],'Turn a broken path into a straight line through reflection.',lambda:S.Line(S.Point(0,-3),S.Point(8,5)).intersection(S.Line(S.Point(0,0),S.Point(1,0)))[0].x,'Exact line intersection after the reflected path argument.'),
q(9,r'Triangle ABC has AB=4, AC=7, and angle BAC=60°. Find BC².',37,[(65,'Omit the cross term in the cosine law.'),(9,'Subtract the side lengths before squaring.'),(93,'Use an obtuse angle sign for the cross term.'),(49,'Treat AB as a projection rather than a full side.')],[r'Drop a perpendicular from B to line AC. Its foot is two units from A and its height is $2\sqrt3$.',r'The horizontal difference from that foot to C is 7-2=5.',r'Therefore BC²=5²+(2√3)²=37.'],['Resolve the side of length four into parallel and perpendicular parts.','Use the 30–60–90 triangle created by the altitude.'],'Derive a distance through a special-triangle projection.',lambda:4**2+7**2-2*4*7*S.Rational(1,2),'Independent cosine-law evaluation.',2),
q(10,r'A right triangle has legs 8 and 15. What is the distance from its right-angle vertex to its incenter?',3*sqrt(2),[(3,'Report the inradius rather than the vertex-to-center distance.'),(6,'Add the two perpendicular distances instead of using the diagonal.'),(sqrt(17),'Use the hypotenuse as a squared distance.'),(F(17,2),'Use the circumradius.')],[r'The hypotenuse is 17, so the inradius is (8+15-17)/2=3.',r'The incenter is three units from both perpendicular legs.',r'In coordinates along those legs it is (3,3), so its distance from their intersection is $3\sqrt2$.'],['Find the radius using area or tangent lengths.','The right-angle bisector places the center equally far from both axes.'],'Combine an incircle radius with local perpendicular geometry.',lambda:sqrt(2)*(S.Rational(8*15,2)/20),'Area-over-semiperimeter radius followed by a coordinate distance.'),
q(11,r'In an isosceles triangle AB=AC=13 and BC=10. The perpendicular from B to AC meets AC at P. Find BP.',F(120,13),[(12,'Use the altitude from A rather than from B.'),(F(60,13),'Forget to double the area.'),(10,'Assume BC is perpendicular to AC.'),(F(119,13),'Report AP instead of BP.')],[r'The symmetry altitude from A has length 12, so the triangle’s area is 60.',r'Using AC as base, the same area is 13·BP/2.',r'Thus BP=120/13. The altitude changes when the chosen base changes.'],['Find the area from the easy symmetry altitude first.','Reuse that area with the requested base.'],'Transfer area between two different altitude constructions.',lambda:sqrt(13**2-S.Rational(119,13)**2),'Projection AP=119/13 gives an independent right-triangle check.'),
q(12,r'A square is inscribed in a right triangle with legs 6 and 8, with one side of the square on the hypotenuse and its opposite vertices on the legs. Find its side length.',F(120,37),[(F(24,7),'Use the formula for a square based at the right-angle vertex.'),(F(24,5),'Use the full triangle altitude.'),(5,'Take half the hypotenuse.'),(F(60,37),'Lose the ratio of the remaining similar triangle.')],[r'The hypotenuse is 10 and its altitude is 24/5. If the square has side s, the remaining triangle above it has altitude 24/5-s.',r'By similarity, its parallel base has length $10(1-5s/24)$, which must equal s.',r'Solving gives 37s=120 and s=120/37. It lies below the full altitude, so the construction fits.'],['Draw the smaller triangle above the square.','Relate its base to its remaining altitude by similarity.'],'Construct a similarity equation for an inscribed figure.',lambda:S.solve(S.Eq(S.Symbol('s')/10,(S.Rational(24,5)-S.Symbol('s'))/S.Rational(24,5)),S.Symbol('s'))[0],'Exact solve of the independent height-ratio model.'),
q(13,r'Two circles of radius 5 have centers 6 units apart. What is the length of their common chord?',8,[(4,'Report half the chord.'),(6,'Use the center separation as the chord.'),(10,'Use a diameter.'),(2*sqrt(34),'Use the full center separation instead of its half in Pythagoras.')],[r'The common chord is perpendicular to the line of centers and bisects it because the radii are equal.',r'Each center is three units from the chord, so the half-chord is $\sqrt{25-9}=4$.',r'The full chord length is 8.'],['Connect both centers to an intersection point.','Symmetry identifies the midpoint of the center segment.'],'Use a symmetry line to create a right triangle.',lambda:2*sqrt(25-3**2),'Circle-coordinate intersection gives y=±4.',2),
q(14,r'A rhombus has diagonals 10 and 24. What is its perimeter?',52,[(34,'Add the two diagonal lengths.'),(68,'Treat half the diagonal sum as a side.'),(104,'Use full diagonals as the legs of the side triangle.'),(48,'Use the longer diagonal as two sides.')],[r'The diagonals of a rhombus bisect each other at right angles.',r'A side is the hypotenuse of a right triangle with legs 5 and 12, hence is 13.',r'Four equal sides give perimeter 52.'],['Use the triangles formed by the intersecting diagonals.','Each leg is half a diagonal.'],'Justify a perpendicular construction from rhombus symmetry.',lambda:4*S.Point(5,0).distance(S.Point(0,12)),'Coordinate distance between adjacent vertices.',2)]
e=[
q(101,r'A triangle has sides 10,17,21. Find its area.',84,[(105,'Use ten as the altitude.'),(168,'Omit the area factor one-half.'),(63,'Assume an altitude of six.'),(42,'Halve the area twice.')],[r'Take the side of length 21 as the horizontal base. Let x be the projection of the side of length ten and h the shared altitude.',r'The right-triangle equations are x²+h²=100 and (21-x)²+h²=289. Subtracting eliminates h² and gives x=6.',r'Then h=8, so the area is 21·8/2=84.',r'The foot lies on the segment because 0<6<21. An independent check uses Heron: the semiperimeter is 24 and the area is √(24·14·7·3)=84.'],['Drop an altitude to the longest side.','Subtract the two Pythagorean equations to remove the height.'],'Make an auxiliary line eliminate an unknown.',lambda:sqrt(24*14*7*3),'Independent Heron calculation.',2),
q(102,r'For A=(0,4), B=(9,8), what is the minimum of AP+PB as P ranges over the x-axis?',15,[(9,'Ignore both vertical distances.'),(sqrt(97),'Use the direct segment AB, which does not pass through the axis.'),(21,'Add horizontal and vertical distances instead of using a straight line.'),(13,'Use the difference of heights after reflecting.')],[r'Reflect A across the axis to A′=(0,-4). For every permitted P, AP=A′P, so the target sum is A′P+PB.',r'The triangle inequality makes this at least A′B=√(9²+12²)=15.',r'The straight segment A′B crosses the x-axis at x=3, so the lower bound is actually attainable.',r'This last check matters: a straight-line lower bound is not always attainable if the moving point is restricted to a smaller segment.'],['Preserve one distance by reflecting its endpoint.','Check whether the straight segment crosses the permitted set.'],'Prove and attain a shortest-path bound.',lambda:S.Point(0,-4).distance(S.Point(9,8)),'Reflected coordinate distance and exact intersection x=3.')]
finish('geometric-constructions','Auxiliary lines: altitude, reflection & extension','Geometry','right-triangles triangle-area angles',30,'367–397',
 [r'A useful auxiliary line is chosen for a purpose: create a right triangle, expose equal areas, produce similar triangles, or turn a broken path into a straight one. Drawing many unmotivated lines usually increases the number of unknowns. Begin by asking what relation is missing.',r'The two examples show different constructions with the same discipline. An altitude creates equations sharing one unknown; a reflection creates a distance that the triangle inequality controls. In both cases, the new object is useful because of a specific invariant.'],
 [section('Perpendiculars reveal shared information',r'When two sides and their included base are known, an altitude creates two right triangles sharing the same height. Label the projection along the base, write both Pythagorean equations, and subtract. The height disappears, leaving a linear equation for the projection. The projection can lie outside the segment in an obtuse triangle; coordinates or signed distances keep the argument valid.',r'An altitude need not be calculated directly. Compute the area using an easy base-height pair, then express the same area using the requested base and unknown altitude. This is particularly effective when an isosceles or right triangle supplies an obvious first height.',r'Connecting an interior point to all three vertices creates an area partition. Equal base lengths can then turn the sum of three areas into a statement about the sum of three distances. The point may move while the total stays fixed; the partition explains the invariant rather than merely illustrating it.'),
 section('Extend or reflect to create a known structure',r'A median can be doubled beyond its midpoint. The resulting quadrilateral has diagonals bisecting each other, hence is a parallelogram. Its side and diagonal relations can recover a median length without pretending that the median is perpendicular or angle-bisecting.',r'Reflection preserves distance to every point on the mirror line. For a shortest path through that line, reflect one endpoint and replace the broken path by a straight segment. The triangle inequality proves a lower bound, while the intersection of the straight segment with the permitted line proves attainability.',r'Check the domain of the moving point. If it is restricted to a segment rather than a whole line, the reflected straight path may cross outside the permitted region. Then an endpoint can minimize the path instead. The drawing suggests a candidate, but the location check completes the solution.'),
 section('Name the relation your construction earns',r'An angle bisector gives a side ratio, not generally two congruent triangles. A median gives equal bases and equal areas, not generally equal angles. An altitude gives right angles, not generally a midpoint. State exactly what the construction guarantees before applying a formula.',r'For a general cevian, Stewart’s theorem relates its length to the two adjacent sides and the pieces of the opposite side. It can be derived by dropping a perpendicular and combining the two Pythagorean equations. Combining this with the angle-bisector ratio is a synthesis step; using the median formula instead loses the needed information.',r'An inscribed square often creates a smaller similar triangle. Express its remaining height and parallel base in terms of the square’s side. Equating the two descriptions yields the dimension. Verify that the result fits inside the original figure, because an algebraic solution outside the geometric range is not a construction.')],
 ['Choose auxiliary lines that eliminate unknowns or expose invariants.','Distinguish altitude, median, and angle-bisector guarantees.','Prove geometric extrema with a feasible equality construction.'],
 [r'Subtract two equations sharing an altitude to recover the base projection.',r'Partition area to relate several perpendicular distances.',r'Reflect one endpoint, apply the triangle inequality, and verify the intersection lies in the permitted set.'],
 'A figure that looks symmetric need not be symmetric. Derive midpoint, perpendicular, and angle-bisector claims from the stated information.',e,p,
 dict(prompt=r'A triangle has sides 9,10,17. Drop an altitude to the side 17, with projection x next to the side 9. Complete the two equations and find the area.',answer=r'$x=135/17$, $h=72/17$, and the area is 36.',steps=[r'$x^2+h^2=81$ and $(17-x)^2+h^2=100$ give x=135/17.',r'Then h²=5184/289, so K=17·(72/17)/2=36.']),
 ['shared-altitude elimination','area invariants','reflection paths','cevian extension'],
 [(r'K=\tfrac12 bh','Base–height area','transferring a known triangle area to a different altitude','h is perpendicular to the line containing the chosen base b.'),(r'b^2m+c^2n=a(d^2+mn)','Stewart’s cevian identity','finding a general cevian length after its base segments are known','$a=m+n=BC$, $b=CA$, $c=AB$, $m=BD$, $n=DC$, and $d=AD$.'),(r'm_a^2=\frac{2b^2+2c^2-a^2}{4}','Median length','finding a median by extending it to a parallelogram diagonal','$a,b,c$ are triangle side lengths and $m_a$ reaches the midpoint of side $a$.'),(r'AP+PB=A\prime P+PB\ge A\prime B','Reflected-path bound','minimizing a broken path constrained to a mirror line','A′ is the reflection of A; P lies on the mirror, and equality needs the straight segment A′B to meet the permitted set.')], 'triangle-area')
